+bool is_mxfp4_mxfp8_gemm(const Tensor &A, const Tensor &B) {
+  if (!is_mxfp_scaling(A.scaling_mode) || !is_mxfp_scaling(B.scaling_mode)) {
+    return false;
+  }
+  return is_fp4_dtype(A.dtype()) != is_fp4_dtype(B.dtype());
