+    NVTE_ERROR("MXFP4 x MXFP8 GEMM supports BF16 and FP32 outputs, got ", to_string(out_dtype),
+               ".");
+  }
+#undef NVTE_MXFP4_MXFP8_GEMM_LAUNCH
